<?php

namespace App\Services;

use App\Models\Item;
use App\Models\Recipe;

/**
 * Keeps the item generated by a recipe (a "preparation") in sync with it.
 */
class PreparationService
{
    public const DEFAULT_CATEGORY = 'Preparaciones';

    /**
     * Create or update the item that exposes the recipe as an ingredient.
     */
    public function publish(Recipe $recipe): Item
    {
        $item = $recipe->item()->first();

        $attributes = [
            'type' => 'preparation',
            'recipe_id' => $recipe->id,
            'name' => $recipe->name,
            'purchase_unit' => 'Lote',
            'purchase_price' => 0,
            'recipe_unit' => $recipe->yield_unit,
            'conversion_factor' => max((float) $recipe->yield_quantity, 0.0001),
            'overhead_type' => null,
        ];

        if ($item) {
            $item->update($attributes);

            return $item;
        }

        return Item::create($attributes + ['category' => self::DEFAULT_CATEGORY]);
    }

    /**
     * Refresh the item data after the recipe header changed.
     */
    public function sync(Recipe $recipe): void
    {
        if (! $recipe->item()->exists()) {
            return;
        }

        $this->publish($recipe);
    }

    /**
     * Remove the generated item if no other recipe consumes it.
     */
    public function unpublish(Recipe $recipe): bool
    {
        $item = $recipe->item()->first();

        if (! $item) {
            return true;
        }

        if ($item->isUsedInRecipes()) {
            return false;
        }

        return (bool) $item->delete();
    }

    /**
     * A preparation cannot be used inside itself, directly or transitively.
     */
    public function wouldCreateCycle(Item $item, Recipe $recipe): bool
    {
        if (! $item->isPreparation() || ! $item->recipe) {
            return false;
        }

        return $item->recipe->id === $recipe->id || $item->recipe->dependsOn($recipe);
    }
}
